entries[310484] = { ["name"] = "Nutcracker Grenade", ["text"] = "2 sec cast\nReagents:\nHandful of Laestrite Bolts (3), Porous Polishing Abrasive (2), Laestrite Ore\nProfession:\nShadowlands Engineering (10)\nTrainer:\nMachinist Au'gur\nZone:\nOribos\nCost:\n30\n\n(2)\nUse: Inflicts 13939 Nature damage to all enemies in a 5 yard radius. (5 Min Cooldown)\n51" }
entries[310485] = { ["name"] = "Shadow Land Mine", ["text"] = "2 sec cast\nReagents:\nHandful of Laestrite Bolts (5), Porous Polishing Abrasive (3), Laestrite Ore (3)\nProfession:\nShadowlands Engineering (20)\nTrainer:\nMachinist Au'gur\nZone:\nOribos\nCost:\n75\n\n(2)\nUse: Place a mine on the ground that explodes when an enemy steps on it, dealing 13939 Shadow damage to all enemies in a 5 yard radius and blasting them away. (5 Min Cooldown)\nRequires Shadowlands Engineering\n(1)" }
entries[310486] = { ["name"] = "Bomb Bola Launcher", ["text"] = "2 sec cast\nReagents:\nNutcracker Grenade (3), Wormfed Gear Assembly , Porous Polishing Abrasive (5), Twilight Bark , Penumbra Thread (10)\nProfession:\nShadowlands Engineering (30)\nTrainer:\nMachinist Au'gur\nZone:\nOribos\nCost:\n1\n15\n\n(2)\nUse: Launch a set of tethered bombs straight ahead, wrapping around the first enemy hit and exploding after 5 seconds, dealing 13939 Fire damage to nearby enemies. (5 Min Cooldown)\nRequires Shadowlands Engineering\n(1)" }
entries[310490] = { ["name"] = "Momentum Redistributor Boots", ["text"] = "2 sec cast 3\nTools: Arclight Spanner , Blacksmith Hammer\nReagents:\nMortal Coiled Spring (10), Handful of Laestrite Bolts (20), Phaedrum Ore (10), Desolate Leather (15), Shrouded Cloth (20)\nProfession:\nShadowlands Engineering (65)\nTrainer:\nMachinist Au'gur\nZone:\nOribos\nCost:\n2\n75\n\nBinds when used\nUse: Redistributes a significant portion of damage you would take from your next fall into nearby enemies. Lasts 10 sec.\n\nCannot be used in instances. (5 Min Cooldown)\nRequires Shadowlands Engineering\n(1)\n\"Allows you to do a super heroic landing!\"" }
entries[310492] = { ["name"] = "Gravimetric Scrambler Cannon", ["text"] = "2 sec cast 3\nTools: Arclight Spanner , Blacksmith Hammer\nReagents:\nWormfed Gear Assembly (3), Mortal Coiled Spring (3), Handful of Laestrite Bolts (20), Porous Polishing Abrasive (20), Solenium Ore (10), Sacred Shard (5)\nProfession:\nShadowlands Engineering (60)\nTrainer:\nMachinist Au'gur\nZone:\nOribos\nCost:\n2\n50\n\nBinds when used\nUse: Destabilizes gravity around a target location, hindering nearby enemies' movement for 10 sec, launching them in random directions, or throwing them up in the air.\n\nUnless it backfires.\nRequires Shadowlands Engineering\n(1)\n\"Sometimes called a \"Black Hole Gun\", which is inaccurate. It's really more of an artillery piece.\"" }
entries[310493] = { ["name"] = "50UL-TR4P", ["text"] = "2 sec cast 3\nTools: Arclight Spanner , Blacksmith Hammer\nReagents:\nWormfed Gear Assembly (3), Mortal Coiled Spring (5), Handful of Laestrite Bolts (10), Phaedrum Ore (10), Soul Dust (5)\nProfession:\nShadowlands Engineering (50)\nTrainer:\nMachinist Au'gur\nZone:\nOribos\nCost:\n2\n\nBinds when used\nUse: Place a containment device on the ground that, once armed, will activate when an enemy steps on it, banishing them for 1 min.\n\nUnless it backfires.\n\nReduced effect against players. (3 Min Cooldown)\nRequires Shadowlands Engineering\n(1)\n\"Who will you be in communications with?!\"" }
entries[310495] = { ["name"] = "Dimensional Shifter", ["text"] = "2 sec cast\nRequires Belt\nTools: Arclight Spanner\nReagents:\nWormfed Gear Assembly , Handful of Laestrite Bolts (10), Sinvyr Ore (3), Umbryl , Immortal Shard\nPermanently attaches a technomagical reality distorter device to your belt, allowing you to turn invisible while out of combat.\nProfession:\nShadowlands Engineering (45)\nTrainer:\nMachinist Au'gur\nZone:\nOribos\nCost:\n1\n75" }
entries[310496] = { ["name"] = "Electro-Jump", ["text"] = "2 sec cast\nRequires Belt\nTools: Arclight Spanner\nReagents:\nWormfed Gear Assembly , Handful of Laestrite Bolts (10), Solenium Ore (3), Oriblase , Immortal Shard\nPermanently attaches a technomagical space-time folding device to your belt, allowing you to instantaneously teleport a short distance in a random direction.\nProfession:\nShadowlands Engineering (45)\nTrainer:\nMachinist Au'gur\nZone:\nOribos\nCost:\n1\n75" }
entries[310497] = { ["name"] = "Damage Retaliator", ["text"] = "2 sec cast\nRequires Belt\nTools: Arclight Spanner\nReagents:\nWormfed Gear Assembly , Handful of Laestrite Bolts (10), Oxxein Ore (3), Angerseye , Immortal Shard\nPermanently attach a technomagical magnetic flux array to your belt that, when activated, suspends several small bladed weapons around you, causing anyone who attacks to take damage.\nProfession:\nShadowlands Engineering (45)\nTrainer:\nMachinist Au'gur\nZone:\nOribos\nCost:\n1\n75" }
