entries[310533] = { ["name"] = "Optical Target Embiggener", ["text"] = "2 sec cast\nTools: Arclight Spanner , Blacksmith Hammer\nReagents:\nWormfed Gear Assembly , Handful of Laestrite Bolts (5), Angerseye , Oriblase\nCreate a permanent weapon enchantment usable only on Guns, Bows, or Crossbows.\nProfession:\nShadowlands Engineering (75)\nTrainer:\nMachinist Au'gur\nZone:\nOribos\nCost:\n3\n50\n\nOptical Target Embiggener\nUse: Permanently attaches a scope to a ranged weapon, causing it to occasionally increase Critical Strike by 824 for 12 sec when dealing damage with ranged attacks.\n\nAttaching this device to a ranged weapon causes it to become soulbound.\n51\n\"Boom. Headshot.\"" }
entries[310534] = { ["name"] = "Infra-green Reflex Sight", ["text"] = "2 sec cast\nTools: Arclight Spanner , Blacksmith Hammer\nReagents:\nWormfed Gear Assembly , Handful of Laestrite Bolts (5), Oriblase (2)\nCreate a permanent weapon enchantment usable only on Guns, Bows, or Crossbows.\nProfession:\nShadowlands Engineering (75)\nTrainer:\nMachinist Au'gur\nZone:\nOribos\nCost:\n3\n50\n\nInfra-green Reflex Sight\nUse: Permanently attaches a scope to a ranged weapon, causing it to occasionally increase Haste by 824 for 12 sec when dealing damage with ranged attacks.\n\nAttaching this device to a ranged weapon causes it to become soulbound.\n51\n\"No one can hide from my sight.\"" }
entries[310535] = { ["name"] = "Wormhole Generator: Shadowlands", ["text"] = "2 sec cast 3\nTools: Arclight Spanner , Blacksmith Hammer\nReagents:\nWormfed Gear Assembly (3), Mortal Coiled Spring (7), Handful of Laestrite Bolts (20), Elethium Ore (3), Solenium Ore (10), Oxxein Ore (10), Phaedrum Ore (10), Sinvyr Ore (10)\nVendor:\nDar Vattish\nZone:\nOribos\nThe Undying Army - Honored\nCost:\n1350\n\nVendor:\nNalcorn Talsen\nZone:\nMaldraxxus\nThe Undying Army - Honored\nCost:\n1350\n\nWormhole Generator: Shadowlands\nBinds when used\nToy\nUse: Open a wormhole that allows the user to quickly travel to one of several fixed points within the Shadowlands. (15 Min Cooldown)\nRequires Shadowlands Engineering\n(1)\n\"CAUTION: Failure to operate within strict safety guidelines may result in... double death? Turbo death? Aliveness?\"" }
entries[310536] = { ["name"] = "Precision Lifeforce Inverter", ["text"] = "3 sec cast 2\nTools: Arclight Spanner\nReagents:\nLaestrite Ore (4), Mortal Coiled Spring , Handful of Laestrite Bolts (4), Twilight Bark (8)\nOptional Reagents:\nProfession:\nShadowlands Engineering (35)\nTrainer:\nMachinist Au'gur\nZone:\nOribos\nCost:\n1\n30\n\nPrecision Lifeforce Inverter\nBinds when equipped\nRanged Gun\n13 - 25 Damage Speed 3.00\n(6.3 damage per second)\n+9 Agility\n+13 Stamina\n+ 9 Random Stat 1\n+ 9 Random Stat 2\nDurability 85 / 85\n50\n\"Extremely effective at making enemy combatants less healthy.\"" }
